package me.vertex.core.trade;
import me.vertex.core.lang.Messages; import org.bukkit.Bukkit; import org.bukkit.OfflinePlayer; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.List;
/** /tradehistory [player] and /tradelogs [all|player]. */
public final class TradeHistoryCommand implements CommandExecutor, TabCompleter { private final TradeManager manager; private final Messages messages; public TradeHistoryCommand(TradeManager manager,Messages messages){this.manager=manager;this.messages=messages;} @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){sender.sendMessage(messages.get(sender,"general.players-only"));return true;}if(!p.hasPermission("vertex.trade.staff.history")){p.sendMessage(messages.get(p,"general.no-permission"));return true;} UUIDAndName target=args.length==0||args[0].equalsIgnoreCase("all")?new UUIDAndName(null,"all trades"):resolve(args[0]);manager.openHistory(p,target.id,target.name,0);return true;}private UUIDAndName resolve(String raw){OfflinePlayer p=Bukkit.getOfflinePlayer(raw);return new UUIDAndName(p.getUniqueId(),p.getName()==null?raw:p.getName());}@Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){return args.length==1?Bukkit.getOnlinePlayers().stream().map(Player::getName).toList():List.of();}private record UUIDAndName(java.util.UUID id,String name){} }
